package pe.com.dentalamericana.messaging;import jakarta.persistence.*;import java.time.Instant;@Entity@Table(name="conversaciones_whatsapp")public class WhatsAppConversation{@Id@GeneratedValue(strategy=GenerationType.IDENTITY)private Long id;@Column(name="paciente_id")private Long patientId;@Column(nullable=false)private String telefono;@Enumerated(EnumType.STRING)@Column(nullable=false)private ConversationStatus estado;@Column(name="ultimo_mensaje_en")private Instant lastMessageAt;@Column(name="creado_en",nullable=false)private Instant createdAt;@Column(name="actualizado_en",nullable=false)private Instant updatedAt;protected WhatsAppConversation(){}public WhatsAppConversation(Long patientId,String phone){this.patientId=patientId;this.telefono=phone;this.estado=ConversationStatus.ABIERTA;}public void touch(){lastMessageAt=Instant.now();}public void derive(){estado=ConversationStatus.DERIVADA;}@PrePersist void create(){Instant n=Instant.now();createdAt=n;updatedAt=n;}@PreUpdate void update(){updatedAt=Instant.now();}public Long getId(){return id;}public Long getPatientId(){return patientId;}public String getPhone(){return telefono;}public ConversationStatus getStatus(){return estado;}public Instant getLastMessageAt(){return lastMessageAt;}}
